CREATE TABLE contacts_default (
    id    BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email TEXT UNIQUE                     -- multiple NULLs allowed
);
CREATE TABLE contacts_strict (
    id    BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email TEXT UNIQUE NULLS NOT DISTINCT  -- PG 15+: only one NULL
);

INSERT INTO contacts_default (email) VALUES (NULL), (NULL);  -- both accepted
INSERT INTO contacts_strict  (email) VALUES (NULL);
INSERT INTO contacts_strict  (email) VALUES (NULL);
-- ERROR: duplicate key value violates unique constraint

-- To make every email case-insensitively unique, index the expression:
CREATE UNIQUE INDEX contacts_strict_email_lower
    ON contacts_strict (lower(email)) NULLS NOT DISTINCT;

CREATE TABLE api_keys (
    id         BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id    BIGINT NOT NULL,
    key_hash   TEXT   NOT NULL,
    revoked_at TIMESTAMPTZ
);

-- A user may have many revoked keys, but only one live key
CREATE UNIQUE INDEX api_keys_one_active
    ON api_keys (user_id)
    WHERE revoked_at IS NULL;

-- Unique on a normalised value
CREATE UNIQUE INDEX users_username_ci_uniq ON users (lower(username));

-- Unique on a prefix (useful for case/whitespace-insensitive codes)
CREATE UNIQUE INDEX promo_codes_norm_uniq ON promo_codes (upper(btrim(code)));
